if(process.env.FIREBASE_PROJECT_ID!=='demo-mongo-audit'||process.env.FIREBASE_AUTH_EMULATOR_HOST!=='127.0.0.1:9298')throw new Error('Tests require isolated audit authentication.');
let mongo,client,database,auth,adminApp,app,store,http,frontendHttp,browser;const accounts={},students=[],offers=[],passwords=new Map();
async function token(email){const response=await fetch('http://127.0.0.1:9298/identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=fake-api-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password:passwords.get(email)||'DemoPassword123!',returnSecureToken:true})});const result=await response.json();assert.ok(result.idToken,JSON.stringify(result));return result.idToken;}
const api=async(role,path,body)=>request(app).post(path).set('Authorization',`Bearer ${await token(accounts[role].email)}`).send(body);
async function admin(data){const response=await api('admin','/api/admin',data);assert.equal(response.status,200,JSON.stringify(response.body));return response.body;}
async function finishTemporary(email){const before=await token(email),changed=await fetch('http://127.0.0.1:9298/identitytoolkit.googleapis.com/v1/accounts:update?key=fake-api-key',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idToken:before,password:'ChangedAudit123!',returnSecureToken:true})}),result=await changed.json();assert.ok(result.idToken,JSON.stringify(result));passwords.set(email,'ChangedAudit123!');const done=await request(app).post('/api/auth/password-complete').set('Authorization','Bearer '+await token(email)).send({});assert.equal(done.status,200,JSON.stringify(done.body));}
before(async()=>{
 frontendHttp=express().use(express.static(fileURLToPath(new URL('../..',import.meta.url)))).listen(5051,'127.0.0.1');
 mongo=await MongoMemoryReplSet.create({replSet:{storageEngine:'wiredTiger'}});({client,database}=await connectDatabase(mongo.getUri('migration_audit')));const firebase=firebaseAdmin();auth=firebase.auth;adminApp=firebase.app;({app,store}=createApp({database,client,auth,demo:true,origins:['http://127.0.0.1:5051']}));http=app.listen(3001);
 for(const role of ['super_admin','admin','subject_faculty','mentor','hod','office','library','accounts']){const email=`mongo-${role}@demo.test`,user=await auth.createUser({email,password:'DemoPassword123!',displayName:role});accounts[role]={uid:user.uid,email};await store.doc(`users/${user.uid}`).set({name:role,email,role,department:'ISE',facultyId:role});}
 await store.doc('settings/workflow').set({library:accounts.library.uid,accounts:accounts.accounts.uid,hodId:accounts.hod.uid,officeId:accounts.office.uid});await store.doc('settings/institution').set({allowedDomains:['demo.test'],departments:['ISE'],sections:['A','B','C']});
});

after(async()=>{await browser?.close();if(frontendHttp)await new Promise(resolve=>frontendHttp.close(resolve));if(http)await new Promise(resolve=>http.close(resolve));await client?.close();await adminApp?.delete();await mongo?.stop();});
test('health, valid tokens, invalid tokens and client role spoofing',async()=>{assert.equal((await request(app).get('/health')).status,200);assert.equal((await request(app).post('/api/data/query').send({path:'users'})).status,401);assert.equal((await request(app).get('/api/auth/profile').set('Authorization','Bearer forged')).status,401);const denied=await api('mentor','/api/admin',{action:'savePolicy',role:'admin',policy:{}});assert.equal(denied.status,403);});
test('teacher provisioning and repeated teacher import retain the Auth UID',async()=>{const row={name:'Mongo Teacher Two',collegeEmail:'mongo-teacher-two@demo.test',phone:'9000000000',department:'ISE',employeeId:'MONGO2',role:'subject_faculty'};const result=await admin({action:'importTeacher',row}),repeat=await admin({action:'importTeacher',row});assert.equal(result.uid,repeat.uid);accounts.teacher2={uid:result.uid,email:row.collegeEmail};assert.equal((await auth.getUser(result.uid)).email,row.collegeEmail);await finishTemporary(row.collegeEmail);});
test('offering CSV semantics resolve exact teachers and preserve context',async()=>{for(const section of ['A','B','C']){const row={department:'ISE',scheme:'2022',semester:5,section,subjectCode:'TEST501',subjectName:'Migration test subject',teacherEmail:section==='B'?accounts.teacher2.email:accounts.subject_faculty.email,credits:'4',components:[{id:'ia1',label:'IA1',max:30},{id:'assignment',label:'Assignment',max:10}]};assert.equal((await admin({action:'previewOfferings',rows:[row]})).valid,1);offers.push({row,...await admin({action:'importOffering',row})});}});
test('student CSV provisioning maps A/B/C students and repeated imports preserve UID/enrollments',async()=>{for(let i=0;i<4;i++){const row={name:i<2?'Duplicate Mongo Name':'Mongo Student '+i,usn:'1AY99IS'+(150+i),collegeEmail:`mongo-student-${i}@demo.test`,phone:'9000000000',department:'ISE',semester:5,section:['A','B','C','B'][i],scheme:'2022',mentorEmail:accounts.mentor.email,role:'student'};const result=await admin({action:'provision',row,requestId:'mongo-student-'+i});students.push({row,...result});accounts['student'+i]={uid:result.uid,email:row.collegeEmail};const repeat=await admin({action:'provision',row,requestId:'mongo-repeat-'+i});assert.equal(repeat.uid,result.uid);assert.equal(await database.collection('enrollments').countDocuments({studentId:result.uid}),1);const enrollment=await database.collection('enrollments').findOne({studentId:result.uid});assert.equal(enrollment.section,row.section);await finishTemporary(row.collegeEmail);}});
test('late offering import backfills all matching students and does not replace marks',async()=>{const row={...offers[1].row,subjectCode:'TEST502'},result=await admin({action:'importOffering',row});assert.equal(await database.collection('enrollments').countDocuments({offeringId:result.id}),2);assert.equal((await admin({action:'importOffering',row})).id,result.id);assert.equal(await database.collection('enrollments').countDocuments({offeringId:result.id}),2);});
test('teacher roster is scoped and student marks remain independent',async()=>{const enrolled=await database.collection('enrollments').find({offeringId:offers[1].id}).toArray();for(let i=0;i<enrolled.length;i++){const result=await api('teacher2','/api/data/write',{operations:[{type:'set',path:'marks/'+enrolled[i]._id,data:{scores:{ia1:10+i,assignment:4+i}}}]});assert.equal(result.status,200,JSON.stringify(result.body));}assert.notDeepEqual((await database.collection('marks').findOne({_id:enrolled[0]._id})).scores,(await database.collection('marks').findOne({_id:enrolled[1]._id})).scores);const response=await api('subject_faculty','/api/data/read',{path:'students/'+students[1].uid});assert.equal(response.status,403);const own=await api('student1','/api/data/query',{path:'marks',filters:[['studentId','==',students[1].uid]]});assert.equal(own.body.rows.length,1);const ownClasses=await api('teacher2','/api/data/query',{path:'offerings',filters:[]});assert.ok(ownClasses.body.rows.every(r=>r.data.teacherId===accounts.teacher2.uid));});
