async function browserLogin(role){if(!browser)browser=await chromium.launch({headless:true,channel:'chrome'});const context=await browser.newContext();await context.route('**/js/firebase-config.js',async route=>route.fulfill({contentType:'text/javascript',body:(await readFile('../js/firebase-config.js','utf8')).replaceAll('demo-digital-no-due','demo-mongo-audit').replaceAll(':9199',':9298').replaceAll('5050','5051')}));await context.route('**/js/api-config.js',route=>route.fulfill({contentType:'text/javascript',body:"export const API_BASE_URL='http://127.0.0.1:3001';"}));context.on('request',r=>{assert.ok(!/firestore.googleapis.com|127\.0\.0\.1:(8180|5001)/.test(r.url()),'Frontend must not contact Firestore/Functions: '+r.url());});const page=await context.newPage();page.setDefaultTimeout(45000);page.on('dialog',d=>d.accept());await page.goto('http://127.0.0.1:5051/login.html');await page.waitForFunction(()=>typeof document.getElementById('resetForm')?.onsubmit==='function');await page.locator('#email').fill(accounts[role].email);await page.locator('#password').fill(passwords.get(accounts[role].email)||'DemoPassword123!');const resolved=page.waitForResponse(response=>response.url().endsWith('/api/auth/login'));await page.getByRole('button',{name:'Log in',exact:true}).click();assert.equal((await resolved).status(),200,'Browser login failed for '+role);await page.waitForURL(/dashboard/);return {page,context};}
test('real Chrome login, student academics, teacher roster, Office duplicates and mobile layouts',async()=>{const login=browserLogin;
 const student=await login('student1');await student.page.getByRole('heading',{name:'My Subjects & Teachers'}).waitFor();assert.equal(await student.page.locator('.subject-item').count(),2);await student.page.goto('http://127.0.0.1:5051/academic.html');await student.page.getByRole('heading',{name:'Subjects & Marks'}).waitFor();assert.match(await student.page.locator('#content').innerText(),/IA1/);for(const width of [1366,768,390]){await student.page.setViewportSize({width,height:900});assert.equal(await student.page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);}await student.context.close();
 const teacher=await login('teacher2');await teacher.page.goto('http://127.0.0.1:5051/academic.html');await teacher.page.locator('.class-button').first().click();await teacher.page.locator('.marks-form').first().waitFor();assert.equal(await teacher.page.locator('.marks-form').count(),2);await teacher.context.close();
 const office=await login('office');await office.page.locator('#usnInput').fill('Duplicate');await office.page.locator('#searchBtn').click();await office.page.getByText('2 students found with this name',{exact:true}).waitFor();assert.equal(await office.page.locator('.office-search-student').count(),2);await office.page.setViewportSize({width:390,height:844});assert.equal(await office.page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await office.context.close();
});
test('real Chrome imports teacher, offering and student CSV through preview and confirm',async()=>{
 const actor=await browserLogin('admin');async function upload(type,headers,row){await actor.page.goto('http://127.0.0.1:5051/admin-dashboard.html');await actor.page.locator('#importType').selectOption(type);const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';await actor.page.locator('#importFile').setInputFiles({name:'isolated.csv',mimeType:'text/csv',buffer:Buffer.from(headers.join(',')+'\n'+headers.map(k=>quote(row[k])).join(','))});await actor.page.locator('#previewBtn').click();await actor.page.waitForFunction(()=>document.getElementById('importProgress')?.textContent.startsWith('Preview ready'));assert.match(await actor.page.locator('#importPreview').innerText(),/0 error rows/);for(const width of [1920,1366,1024,768,390]){await actor.page.setViewportSize({width,height:900});assert.ok(await actor.page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'CSV preview overflow '+width);} await actor.page.locator('#acceptWarnings').check();await actor.page.locator('#importBtn').click();await actor.page.waitForFunction(()=>document.getElementById('importProgress')?.textContent.includes('rows completed'));assert.match(await actor.page.locator('#importProgress').innerText(),/0 failed or skipped/);}
 await upload('teachers',['name','collegeEmail','phone','department','employeeId','role'],{name:'CSV UI Teacher',collegeEmail:'mongo-ui-teacher@demo.test',phone:'9000000000',department:ISE_LABEL,employeeId:'MONGO-UI',role:'subject_faculty'});
 await upload('offerings',['department','scheme','semester','section','subjectCode','subjectName','teacherEmail','credits','components'],{department:ISE_LABEL,scheme:'2022',semester:5,section:'C',subjectCode:'UIT501',subjectName:'Browser CSV course',teacherEmail:'mongo-ui-teacher@demo.test',credits:4,components:JSON.stringify([{id:'ia1',label:'IA1',max:30},{id:'assignment',label:'Assignment',max:10}])});
 const row={name:'CSV UI Student',usn:'1AY99IS199',collegeEmail:'mongo-ui-student@demo.test',phone:'9000000000',department:ISE_LABEL,semester:5,section:'C',scheme:'2022',mentorEmail:accounts.mentor.email};await upload('students',['name','usn','collegeEmail','phone','department','semester','section','scheme','mentorEmail'],row);await upload('students',['name','usn','collegeEmail','phone','department','semester','section','scheme','mentorEmail'],row);const profile=await database.collection('students').findOne({usn:row.usn});assert.ok(profile);assert.equal(await database.collection('students').countDocuments({usn:row.usn}),1);assert.equal(await database.collection('enrollments').countDocuments({studentId:profile._id}),2);await actor.context.close();
});
test('real Chrome completes Student → teachers/Library/Accounts → Mentor → HOD → Office',async()=>{
 const actor=await browserLogin('student0');await actor.page.goto('http://127.0.0.1:5051/create-request.html');await actor.page.locator('#confirmCheck').check();await actor.page.locator('#submitBtn').click();await actor.page.waitForURL(/student-dashboard/);const r=await database.collection('noDueRequests').findOne({studentId:students[0].uid}),id=r._id;
 for(const role of ['subject_faculty','library','accounts']){const approval=await browserLogin(role);await approval.page.goto('http://127.0.0.1:5051/approver-dashboard.html#requests');const key=role==='subject_faculty'?'subject_'+offers[0].id:role;const row=approval.page.locator(`[data-path="noDueRequests/${id}/approvals/${key}"]`);await row.waitFor();await row.locator('.approve-btn').click();for(let i=0;i<100;i++){if((await database.collection('noDueRequests').findOne({_id:id})).approvalStates[key]==='approved')break;await new Promise(r=>setTimeout(r,100));}assert.equal((await database.collection('noDueRequests').findOne({_id:id})).approvalStates[key],'approved');await approval.context.close();}
 for(const role of ['mentor','hod']){const approval=await browserLogin(role);await approval.page.goto(`http://127.0.0.1:5051/${role}-dashboard.html#requests`);const row=approval.page.locator(`[data-request-id="${id}"]`);await row.waitFor();await row.locator('.approve-btn').click();for(let i=0;i<100;i++){if((await database.collection('noDueRequests').findOne({_id:id})).status===(role==='mentor'?'pending_hod':'cleared'))break;await new Promise(r=>setTimeout(r,100));}await approval.context.close();}
 const office=await browserLogin('office');await office.page.locator(`[data-request-id="${id}"]`).click();for(let i=0;i<100;i++){if((await database.collection('noDueRequests').findOne({_id:id})).status==='issued')break;await new Promise(r=>setTimeout(r,100));}assert.equal((await database.collection('noDueRequests').findOne({_id:id})).status,'issued');await actor.page.reload();await actor.page.getByText('Hall ticket issued',{exact:false}).first().waitFor();await office.context.close();await actor.context.close();
});
