async function isolatedPage(){if(!browser)browser=await chromium.launch({headless:true,channel:'chrome'});const context=await browser.newContext();await context.route('**/js/firebase-config.js',async r=>r.fulfill({contentType:'text/javascript',body:(await readFile('../js/firebase-config.js','utf8')).replaceAll('demo-digital-no-due','demo-mongo-audit').replaceAll(':9199',':9298').replaceAll('5050','5051')}));await context.route('**/js/api-config.js',r=>r.fulfill({contentType:'text/javascript',body:"export const API_BASE_URL='http://127.0.0.1:3001';"}));const page=await context.newPage();page.setDefaultTimeout(30000);return {page,context};}
async function reminderBrowserFlow(email,identifier,newPassword){
 const {page,context}=await isolatedPage();
 const login=async password=>{await page.goto('http://127.0.0.1:5051/login.html');await page.locator('#email').fill(identifier);await page.locator('#password').fill(password);await page.getByRole('button',{name:'Show password',exact:true}).click();assert.equal(await page.locator('#password').getAttribute('type'),'text');await page.getByRole('button',{name:'Hide password',exact:true}).click();await page.getByRole('button',{name:'Log in',exact:true}).click();};
 await login('DemoPassword123!');await page.waitForURL(/dashboard/);const home=page.url();await page.locator('#passwordReminder').waitFor();
 assert.match(await page.locator('#passwordReminderMessage').innerText(),/You are currently using the default temporary password./);
 for(const width of [390,768,1366]){await page.setViewportSize({width,height:900});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));assert.ok(await page.locator('#passwordReminder').evaluate(e=>{const r=e.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth;}));await mkdir('test/browser-artifacts',{recursive:true});await page.screenshot({path:`test/browser-artifacts/password-reminder-${width}.png`});}
 await page.getByRole('button',{name:'Remind me later',exact:true}).click();assert.equal(await page.locator('#passwordReminder').count(),0);
 await page.goto('http://127.0.0.1:5051/academic.html');await page.waitForTimeout(700);assert.ok(page.url().endsWith('academic.html'));assert.equal(await page.locator('#passwordReminder').count(),0);
 await page.goto(home);await page.waitForTimeout(700);assert.equal(await page.locator('#passwordReminder').count(),0);await page.reload();await page.waitForTimeout(700);assert.equal(await page.locator('#passwordReminder').count(),0);
 await page.locator('#logoutBtn').click();await page.waitForURL(/login/);await login('DemoPassword123!');await page.waitForURL(/dashboard/);await page.locator('#passwordReminder').waitFor();
 await page.locator('#passwordReminder').getByRole('button',{name:'Change password',exact:true}).click();await page.waitForURL(/password-settings/);assert.equal(await page.locator('#backLink').isVisible(),true);assert.equal(await page.locator('.password-toggle').count(),3);
 await page.locator('#currentPassword').fill('DemoPassword123!');await page.locator('#newPassword').fill(newPassword);await page.locator('#confirmPassword').fill(newPassword);await page.locator('button[type=submit]').click();await page.waitForURL(/login/);passwords.set(email,newPassword);await page.locator('#passwordChangedNotice').waitFor();assert.equal(await page.evaluate(async()=>{const {auth}=await import('/js/firebase-config.js');await auth.authStateReady();return auth.currentUser;}),null);
 await login('DemoPassword123!');await page.locator('#loginError:not(.hidden)').waitFor();await page.locator('#password').fill(newPassword);await page.getByRole('button',{name:'Log in',exact:true}).click();await page.waitForURL(/dashboard/);await page.waitForTimeout(700);assert.equal(await page.locator('#passwordReminder').count(),0);await context.close();
}

